import{_ as t,l as r,o as a,c as i,v as n,p as s,x as o,d as p,i as E,S as d}from"./chunks/framework.InCnrqk-.js";const O=JSON.parse('{"title":"货币同盟","description":"","frontmatter":{"title":"货币同盟","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/monetary-union.md","filePath":"econ/monetary-union.md","lastUpdated":1789023840000}'),A={name:"econ/monetary-union.md"};function c(B,e,h,m,u,_){const l=r("Mermaid");return a(),i("div",null,[e[1]||(e[1]=n('<h1 id="货币同盟" tabindex="-1">货币同盟 <a class="header-anchor" href="#货币同盟" aria-label="Permalink to &quot;货币同盟&quot;">​</a></h1><div class="epigraph"><p>最优货币区问的不是「要不要固定汇率」，而是：在哪一组冲击与要素流动下，交出独立货币的代价小于节省的兑换与承诺成本。</p><footer>—— Mundell, A Theory of Optimum Currency Areas, American Economic Review, 1961</footer></div><p><a href="/econ/exchange-regimes">上一课</a>把安排分成硬钉、中间与浮动。硬钉住已经让 \\(M\\) 内生。本课缺口是把硬钉住推到极限：若干经济体共用一种货币、没有各自的 \\(E\\) 与 \\(M\\)。Mundell（1961）的最优货币区（OCA）给出何时这种极限比各自浮动更划算。不重画制度邮票，不把欧元史写成年表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>浮动让 \\(E\\) 吸收不对称冲击；钉住把冲击留给物价、产出或要素流动。货币同盟是不可逆的硬钉住加共同央行：成员国不能再贬本国货币，也不能单独扩 \\(M\\)。Mundell 问：若冲击在区域间不对称，而劳动力（或更一般的要素）在区内可流动，谁还需要各自的 \\(E\\)？流动把失业从受冲击区抽走，汇率工具变得多余。</p><p>缺口不是再讲三角的哪两个顶点，而是：同盟的边界应由冲击对称性与要素流动来画，不由国界印章来画。下一课不可能三角会把「交出独立货币」收成三选二的一角；本课先把这一角的福利条件写清。</p><p><span class="marginnote">1961 年的标准是要素流动。后来的清单加上贸易一体化、财政转移、金融一体化与名义刚性——那是补充，不是把 Mundell 改写成「政治愿意即可」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>比较两种调整技术。不对称需求下降落在 A 区：若 A 有独立货币，贬值可转换支出；若 A 与 B 共用货币，调整靠 A 的工资物价下降，或劳动力迁到 B，或财政转移。OCA 说：要素流动充分时，第二种技术够用，节省兑换成本与各自货币的承诺噪音。流动不充分且冲击不对称时，各自浮动（或至少保留 \\(E\\)）更便宜。</p>',9)),(a(),s(d,null,{default:o(()=>[E(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHOCK%5B%22%E4%B8%8D%E5%AF%B9%E7%A7%B0%E5%86%B2%E5%87%BB%22%5D%20--%3E%20FLOAT%5B%22%E5%90%84%E8%87%AA%20E%3A%20%E6%94%AF%E5%87%BA%E8%BD%AC%E6%8D%A2%22%5D%0A%20%20SHOCK%20--%3E%20UNION%5B%22%E5%85%B1%E7%94%A8%E8%B4%A7%E5%B8%81%22%5D%0A%20%20UNION%20--%3E%20MOB%5B%22%E8%A6%81%E7%B4%A0%E6%B5%81%E5%8A%A8%20%2F%20%E5%B7%A5%E8%B5%84%E5%BC%B9%E6%80%A7%22%5D%0A%20%20UNION%20--%3E%20STUCK%5B%22%E6%B5%81%E5%8A%A8%E4%B8%8D%E8%B6%B3%3A%20%E5%A4%B1%E4%B8%9A%E9%9B%86%E4%B8%AD%22%5D%0A%20%20MOB%20--%3E%20OK%5B%22OCA%3A%20%E4%B8%8D%E5%BF%85%E5%90%84%E8%87%AA%E8%B4%A7%E5%B8%81%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=n('<p>McKinnon 强调开放度：可贸易比重高时，各自浮动的 \\(q\\) 波动更伤。Kenen 强调产品多样化：多样化本身平滑产业冲击。本课以 Mundell 的流动标准为最小定义，其余作边界上的加项。</p><h3 id="同盟不是「永远钉住」的修辞" tabindex="-1">同盟不是「永远钉住」的修辞 <a class="header-anchor" href="#同盟不是「永远钉住」的修辞" aria-label="Permalink to &quot;同盟不是「永远钉住」的修辞&quot;">​</a></h3><p>货币局仍可退出。同盟取消了本国货币，退出是另一场制度变迁。Obstfeld–Rogoff 的中间幻象在此反过来：同盟把承诺做硬，代价是失去 \\(E\\) 与本国最后贷款人——除非共同机构把它们接过去。原罪国家加入储备货币同盟，可以减轻币种错配，同时放弃独立铸币税。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是把名义调整从汇率挪到数量与要素价格。共同货币删掉区内 \\(E\\) 的超调，也删掉用贬值做净值税或转换的选项。工资若粘，数量（失业）承担冲击，直到相对物价慢慢动。要素流动把数量调整从失业改成迁移。财政若能跨区保险，需求冲击被转移吸收——1961 年正文并没有把财政联盟写全，后文的欧元辩论才补。</p><p>长期中性：同盟的 \\(\\pi\\) 由共同名义锚决定。成员国不能靠本国 \\(H\\) 征独立通胀税。三角下一课会说：资本流动加共同货币，独立货币已经交出去。本课只钉 OCA 的成本收益，不把三选二提前写成定理。</p><p><span class="marginnote">内生 OCA：加入同盟后贸易与金融一体化加深，对称性可以后验提高。这是 Frankel–Rose 一类补充，不能事前把任何一组国家说成已经满足 1961 年标准。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 OCA 写成「大国就该有独立货币」。标准是冲击与流动，不是面积。也不要把共同货币区内的支付系统写成限价簿。下一课 <a href="/econ/impossible-trinity">不可能三角</a>把独立货币、钉住、资本开放收成三选二；同盟是已经选了「钉住（极端）+ 资本可开、货币上交」。</p><p>后课默认：货币同盟是硬钉住加交出 \\(M\\)；是否最优看不对称冲击与要素流动。中间制度的幻象与同盟的硬承诺是同一菜单上的两端。</p><p>马歇尔–勒纳与 J 曲线仍适用于对区外的 \\(E\\)；区内没有各自的 \\(E\\) 可贬。</p><p>共同央行的最后贷款人是对同盟整体，不是对某一个成员国的财政。银行若持有本国主权债，同盟内部仍可有原罪式的环。那是后课银行与主权的接缝，本课先把 OCA 的调整技术钉死。</p><p>不要用「已经加入所以一定是 OCA」倒推 1961 年标准。政治承诺可以先于要素流动；Mundell 问的是代价，不是入场券。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Mundell 1961：要素流动充分、冲击可被数量吸收时，共用货币划算。</li><li>同盟是不可逆硬钉住：失去各自的 \\(E\\) 与 \\(M\\)，换承诺与兑换成本。</li><li>开放度、多样化、财政保险是后补条件，不是 1961 年的最小定义。</li><li>区内没有各自的 \\(E\\) 可贬；对区外仍有马歇尔–勒纳与 J 曲线。</li><li>下一课不可能三角把「交出独立货币」收成三选二的一角。</li><li>出处：Mundell, <em>AER</em> 1961；制度菜单见上一课 Obstfeld–Rogoff 与 IMF 口径。</li></ul>',15))])}const C=t(A,[["render",c]]);export{O as __pageData,C as default};
